// Parse report configuration
const input = $input.first().json;

const reportType = input['Report Type'] || 'Weekly';
let startDate, endDate;

const now = new Date();

switch (reportType) {
  case 'Weekly':
    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    endDate = now;
    break;
  case 'Monthly':
    startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    endDate = new Date(now.getFullYear(), now.getMonth(), 0);
    break;
  case 'Quarterly':
    const quarter = Math.floor(now.getMonth() / 3);
    startDate = new Date(now.getFullYear(), (quarter - 1) * 3, 1);
    endDate = new Date(now.getFullYear(), quarter * 3, 0);
    break;
  default:
    startDate = input['Start Date'] ? new Date(input['Start Date']) : new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    endDate = input['End Date'] ? new Date(input['End Date']) : now;
}

const channels = input['Include Channels'] || 'Website/Google Analytics,Social Media,Email Marketing,Paid Advertising';

return {
  json: {
    reportType,
    startDate: startDate.toISOString().split('T')[0],
    endDate: endDate.toISOString().split('T')[0],
    channels: typeof channels === 'string' ? channels.split(',').map(c => c.trim()) : channels,
    campaign: input['Campaign Name (if specific)'] || '',
    recipients: input['Email Recipients'] || 'marketing@company.com'
  }
};

// Prepare config for parallel data fetching
const config = $input.first().json;

return {
  json: {
    ...config,
    fetchStarted: new Date().toISOString()
  }
};

