return { json: { email: emailMetrics } };

// Fetch paid advertising metrics
const config = $input.first().json;

// In production, this would use Google Ads, Facebook Ads APIs
const adMetrics = {
  source: 'Paid Advertising',
  period: { start: config.startDate, end: config.endDate },

  // Overall spend
