    }
  },

  // Top campaigns
  topCampaigns: [
    { name: 'Brand Awareness', platform: 'Facebook', roas: '3.2x' },
    { name: 'Lead Gen', platform: 'Google', roas: '4.1x' },
    { name: 'Retargeting', platform: 'Google', roas: '5.8x' }
  ]
