return { json: { advertising: adMetrics } };

// Calculate marketing KPIs from all sources
const items = $input.all();

// Combine all metrics
let website = {}, social = {}, email = {}, advertising = {};
items.forEach(item => {
  if (item.json.website) website = item.json.website;
  if (item.json.social) social = item.json.social;
  if (item.json.email) email = item.json.email;
  if (item.json.advertising) advertising = item.json.advertising;
});

const formatNumber = (n) => n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const formatCurrency = (n) => '$' + n.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

// Calculate overall KPIs
const kpis = {
  // Traffic
  totalWebsiteVisits: website.sessions || 0,
  totalReach: (website.sessions || 0) + (social.totalReach || 0) + (advertising.impressions || 0),

  // Engagement
  totalEngagements: (social.totalEngagements || 0) + (email.clicks || 0) + (advertising.clicks || 0),
  avgEngagementRate: ((parseFloat(social.platforms?.linkedin?.engagementRate || 0) + 
                       parseFloat(social.platforms?.facebook?.engagementRate || 0)) / 2).toFixed(2),

  // Leads & Conversions
  totalConversions: (website.goalCompletions || 0) + (advertising.conversions || 0),
  totalNewLeads: (email.newSubscribers || 0) + (advertising.conversions || 0),
  avgConversionRate: (((parseFloat(website.conversionRate) || 0) + 
                       (parseFloat(advertising.conversionRate) || 0)) / 2).toFixed(2),

  // Email performance
  emailOpenRate: email.openRate || 0,
  emailClickRate: email.clickRate || 0,

  // Ad performance
  adSpend: advertising.totalSpend || 0,
  adRevenue: advertising.revenue || 0,
  roas: advertising.roas || 0,

  // Social growth
  followerGrowth: social.followerGrowth || 0,

  // Cost efficiency
  costPerLead: advertising.totalSpend && advertising.conversions 
    ? (advertising.totalSpend / advertising.conversions).toFixed(2) 
    : 0
};

// Format for display
const formattedKpis = {
  totalWebsiteVisits: formatNumber(kpis.totalWebsiteVisits),
  totalReach: formatNumber(kpis.totalReach),
  totalEngagements: formatNumber(kpis.totalEngagements),
  avgEngagementRate: kpis.avgEngagementRate + '%',
  totalConversions: formatNumber(kpis.totalConversions),
  totalNewLeads: formatNumber(kpis.totalNewLeads),
  avgConversionRate: kpis.avgConversionRate + '%',
  emailOpenRate: kpis.emailOpenRate + '%',
  emailClickRate: kpis.emailClickRate + '%',
  adSpend: formatCurrency(kpis.adSpend),
  adRevenue: formatCurrency(kpis.adRevenue),
  roas: kpis.roas + 'x',
  followerGrowth: '+' + formatNumber(kpis.followerGrowth),
  costPerLead: formatCurrency(parseFloat(kpis.costPerLead) || 0)
};

return {
  json: {
    kpis,
    formattedKpis,
    website,
    social,
    email,
    advertising
  }
};

