// Generate HTML report
const data = $input.first().json;

// Parse AI insights
let insights = {
  executiveSummary: 'Marketing performance report generated.',
  wins: [],
  improvements: [],
  channelRecommendations: {},
  budgetSuggestions: ''
};

try {
  const aiOutput = data.output || '';
  const jsonMatch = aiOutput.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    insights = { ...insights, ...JSON.parse(jsonMatch[1]) };
  }
} catch (e) {}

const report = {
  title: 'Marketing Performance Report',
  generatedAt: new Date().toISOString(),
  kpis: data.formattedKpis,
  insights,
  website: data.website,
  social: data.social,
  email: data.email,
  advertising: data.advertising
};

return { json: report };

